-- Groupe d'allemand: database setup and starting content. Paste everything into Supabase > SQL Editor > New query, then Run.
-- Before running, replace VOTRE_EMAIL@exemple.fr below with the e-mail you will sign in with (you become moderator).

create table if not exists public.docs (
  collection text not null,
  id text not null,
  data jsonb not null default '{}'::jsonb,
  author uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (collection, id)
);
alter table public.docs enable row level security;
alter table public.docs replica identity full;

create table if not exists public.admins (email text primary key);
alter table public.admins enable row level security;
insert into public.admins (email) values (lower('VOTRE_EMAIL@exemple.fr')) on conflict do nothing;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins where email = lower(auth.jwt() ->> 'email'))
$$;

-- Members (signed-in users) can read everything.
drop policy if exists "read" on public.docs;
create policy "read" on public.docs for select to authenticated using (true);

-- Anyone signed in can publish events, posts, stories and comments, and write their own profile and participation.
-- Festival programmes and news: moderator only.
drop policy if exists "insert" on public.docs;
create policy "insert" on public.docs for insert to authenticated with check (
  author = auth.uid() and (
    public.is_admin()
    or collection in ('events', 'posts', 'stories', 'comments')
    or (collection in ('profiles', 'attendance') and id = auth.uid()::text)
  )
);

-- Each member edits and deletes only their own items; the moderator can edit and delete everything.
drop policy if exists "update" on public.docs;
create policy "update" on public.docs for update to authenticated
  using (public.is_admin() or author = auth.uid())
  with check (public.is_admin() or author = auth.uid());

drop policy if exists "delete" on public.docs;
create policy "delete" on public.docs for delete to authenticated
  using (public.is_admin() or author = auth.uid());

-- Live updates.
do $$ begin
  alter publication supabase_realtime add table public.docs;
exception when duplicate_object then null; end $$;

-- Files for the Ressources tab (public links, uploads by signed-in members into their own folder).
insert into storage.buckets (id, name, public) values ('ressources', 'ressources', true) on conflict do nothing;
drop policy if exists "ressources upload" on storage.objects;
create policy "ressources upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'ressources' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "ressources delete" on storage.objects;
create policy "ressources delete" on storage.objects for delete to authenticated
  using (bucket_id = 'ressources' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));


